    [Fact]
    public void UnknownEnumValueIsPreserved()
    {
        var known = JsonSerializer.Deserialize<FeedSection>("\"auto\"", TungoJson.Options);
        Assert.True(known.IsKnown);
        Assert.Equal(FeedSection.Auto, known);

        var unknown = JsonSerializer.Deserialize<FeedSection>("\"brand_new\"", TungoJson.Options);
        Assert.False(unknown.IsKnown);
        Assert.Equal("brand_new", unknown.Value);
        Assert.Equal("\"brand_new\"", JsonSerializer.Serialize(unknown, TungoJson.Options));
        Assert.NotEqual(FeedSection.Auto, unknown);
        Assert.Equal(string.Empty, default(FeedSection).Value);
    }

    [Fact]
    public void UnknownPropertiesSurviveARoundTrip()
    {
        const string Json = "{\"id\":\"d1\",\"title\":\"Report\",\"future\":{\"a\":[1,2]}}";
        var renamed = JsonSerializer.Deserialize(Json, TungoJsonContext.Shared.ChatDialogRenamed)!;
        Assert.Equal("d1", renamed.Id);
        Assert.Equal("Report", renamed.Title);
        Assert.NotNull(renamed.AdditionalProperties);
        Assert.Equal(2, renamed.AdditionalProperties["future"].GetProperty("a")[1].GetInt32());
        Assert.Equal(Json, JsonSerializer.Serialize(renamed, TungoJsonContext.Shared.ChatDialogRenamed));
    }

    [Fact]
    public void MissingRequiredPropertyFailsDecodingExceptInEvents()
    {
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize("{\"id\":\"d1\"}", TungoJsonContext.Shared.ChatDialogRenamed));
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize<ChatDialogRenamed>("{\"id\":\"d1\"}", TungoJson.Options));

        // Events and error details are read tolerantly, nested values included.
        var partial = JsonSerializer.Deserialize("{\"id\":\"d1\"}", TungoJsonContext.Tolerant.ChatDialogRenamed)!;
        Assert.Equal("d1", partial.Id);
        Assert.Null(partial.Title);
        var step = JsonSerializer.Deserialize("{\"type\":\"text\",\"step\":2}", TungoJsonContext.Tolerant.ChatEvent)!;
        Assert.Null(step.AsText!.Delta);
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize("{\"type\":\"text\",\"step\":2}", TungoJsonContext.Shared.ChatEvent));
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize("{\"type\":\"text\",\"delta\":5}", TungoJsonContext.Tolerant.ChatEvent));
        Assert.Throws<JsonException>(() => JsonSerializer.Deserialize("{\"id\":5,\"title\":\"t\"}", TungoJsonContext.Shared.ChatDialogRenamed));
    }

