    }

    [Fact]
    public void OptionalDistinguishesAbsentFromNull()
    {
        Assert.Equal("{}", JsonSerializer.Serialize(new WebhookEndpointPatch(), TungoJsonContext.Shared.WebhookEndpointPatch));
        Assert.Equal(
            "{\"event_types\":null}",
            JsonSerializer.Serialize(new WebhookEndpointPatch { EventTypes = null }, TungoJsonContext.Shared.WebhookEndpointPatch));
        Assert.Equal(
            "{\"event_types\":[\"ping\"]}",
            JsonSerializer.Serialize(new WebhookEndpointPatch { EventTypes = new[] { "ping" } }, TungoJsonContext.Shared.WebhookEndpointPatch));

        var absent = JsonSerializer.Deserialize("{}", TungoJsonContext.Shared.WebhookEndpointPatch)!;
        Assert.False(absent.EventTypes.HasValue);
        Assert.Throws<InvalidOperationException>(() => absent.EventTypes.Value);
        var explicitNull = JsonSerializer.Deserialize("{\"event_types\":null}", TungoJsonContext.Shared.WebhookEndpointPatch)!;
        Assert.True(explicitNull.EventTypes.HasValue);
        Assert.Null(explicitNull.EventTypes.Value);
        var set = JsonSerializer.Deserialize("{\"event_types\":[\"ping\"]}", TungoJsonContext.Shared.WebhookEndpointPatch)!;
        Assert.Equal(new[] { "ping" }, set.EventTypes.Value);
        Assert.NotEqual(absent.EventTypes, explicitNull.EventTypes);
    }

    [Fact]
