        const string Json = "{\"amount_tiyn\":9007199254740993,\"api_key_id\":null,\"at\":\"2026-01-01T00:00:00+05:00\",\"balance_after_tiyn\":-9223372036854775808,"
            + "\"id\":\"l1\",\"kind\":\"usage\",\"model\":null,\"note\":null,\"payment_id\":null,\"request_id\":null}";
        var entry = JsonSerializer.Deserialize(Json, TungoJsonContext.Shared.PlatformLedgerEntry)!;
        Assert.Equal(9007199254740993L, entry.AmountTiyn);
        Assert.Equal(long.MinValue, entry.BalanceAfterTiyn);
        Assert.Equal("2026-01-01T00:00:00+05:00", entry.At);
        Assert.Contains("9007199254740993", JsonSerializer.Serialize(entry, TungoJsonContext.Shared.PlatformLedgerEntry), StringComparison.Ordinal);
    }

    [Fact]
    public void TaggedUnionSelectsTheVariantAndKeepsUnknownOnes()
    {
        var text = JsonSerializer.Deserialize("{\"type\":\"text\",\"delta\":\"Hi\",\"step\":2}", TungoJsonContext.Shared.ChatEvent)!;
        Assert.False(text.IsUnknown);
        Assert.Equal("text", text.Type);
        Assert.IsType<ChatEventText>(text.Value);
        Assert.Equal("Hi", text.AsText!.Delta);
        Assert.Equal(2.0, text.AsText.Step);
        Assert.Null(text.AsDone);

        const string Unknown = "{\"type\":\"hologram\",\"depth\":3}";
        var unknown = JsonSerializer.Deserialize(Unknown, TungoJsonContext.Shared.ChatEvent)!;
        Assert.True(unknown.IsUnknown);
        Assert.Equal("hologram", unknown.Type);
        Assert.Equal(Unknown, JsonSerializer.Serialize(unknown, TungoJsonContext.Shared.ChatEvent));

        ChatEvent built = new ChatEventText { Delta = "x" };
        using var written = JsonDocument.Parse(JsonSerializer.Serialize(built, TungoJsonContext.Shared.ChatEvent));
        Assert.Equal("text", written.RootElement.GetProperty("type").GetString());
        Assert.Equal("x", written.RootElement.GetProperty("delta").GetString());
    }

