        Assert.Equal("abc", text.AsString);
        Assert.Null(text.AsNumber);
        var number = JsonSerializer.Deserialize("12.5", TungoJsonContext.Shared.AutomationRunDetailOutputValue)!;
        Assert.Equal(12.5, number.AsNumber);
        Assert.Equal(12.5m, number.AsDecimal);
        Assert.Null(number.AsBoolean);
        var flag = JsonSerializer.Deserialize("true", TungoJsonContext.Shared.AutomationRunDetailOutputValue)!;
        Assert.True(flag.AsBoolean);

        // A JSON kind the contract does not list today is kept instead of failing.
        var future = JsonSerializer.Deserialize("{\"k\":1}", TungoJsonContext.Shared.AutomationRunDetailOutputValue)!;
        Assert.Equal("{\"k\":1}", JsonSerializer.Serialize(future, TungoJsonContext.Shared.AutomationRunDetailOutputValue));

        AutomationRunDetailOutputValue built = "abc";
        Assert.Equal("\"abc\"", JsonSerializer.Serialize(built, TungoJsonContext.Shared.AutomationRunDetailOutputValue));
    }

